mapper.select:
SELECT payment_no, order_no, user_id, amount, pay_type, pay_status, third_trade_no, paid_at FROM payment WHERE deleted = 0
AND payment_no = #{paymentNo}
AND order_no = #{orderNo}
AND pay_status = #{payStatus}
AND paid_at >= #{startTime}
AND paid_at <= #{endTime}
ORDER BY paid_at DESC, created_at DESC
